// PASCAL-style archive Run: reveal saved source contributions, then edges and families.
const originalDrawOntology=drawOntology;
const originalDrawMaintenance=drawMaintenance;
const originalDrawMiddle=drawMiddle;
const originalColumnRows=columnRows;
state.reveal=null;state.buildTimer=null;state.maintenanceTimer=null;
function cancelBuild(){clearTimeout(state.buildTimer);clearTimeout(state.maintenanceTimer);state.buildTimer=null;state.maintenanceTimer=null;}
const originalStop=stop;
stop=function(){originalStop();cancelBuild();};
drawMiddle=function(){originalDrawMiddle();$('#detail .lbl').textContent=(state.dataset||'BIRD-History')+' · '+state.db.database;$('#detail .sr-source-badge').textContent='Saved ontology · recovered names';$('#detail .sr-metrics').innerHTML=$('#detail .sr-metrics').innerHTML.replace('history SQL','source records');
 const o=state.db.ontology;
 const tableAlias=new Map(Object.entries(state.db.sql_table_aliases||{}).map(([table,aliases])=>[table,new Set(aliases)]));for(const src of o.sources){for(const m of src.sql.matchAll(/(?:FROM|JOIN)\s+["`]?([\w]+)["`]?\s+(?:AS\s+)?([A-Za-z]\w*)/gi)){if(!['WHERE','INNER','LEFT','RIGHT','JOIN','GROUP','ORDER','ON','LIMIT','UNION'].includes(m[2].toUpperCase())){if(!tableAlias.has(m[1]))tableAlias.set(m[1],new Set());tableAlias.get(m[1]).add(m[2]);}}}
 const schema=`<details class="sr-native-block"><summary>DB schema / table aliases</summary>${o.tables.map(t=>`<details class="sr-json"><summary>${esc(t.physical_table)} <small>${t.columns.length} cols · SQL aliases: ${esc([...(tableAlias.get(t.physical_table)||[])].join(', ')||'—')}</small></summary>${code('CREATE TABLE "'+t.physical_table+'" (\n'+t.columns.map(c=>'  "'+c.physical_column+'" '+(c.declared_type||'unknown')).join(',\n')+'\n);')}${details('Saved table-level recovery',o.recovery.find(r=>r.prediction?.physical_table===t.physical_table)?.prediction||{})}</details>`).join('')}</details>`;
 const kb=o.objects.filter(x=>['metric','binding','predicate','program'].includes(x.kind));
 const business=`<details class="sr-native-block"><summary>Business semantics / 已有业务口径 · ${kb.length}</summary><div class="sr-kb-scroll">${kb.map(x=>`<details class="sr-json" data-semantic-id="${esc(x.id)}"><summary><span class="sr-source-id">${esc(x.kind)}</span> ${esc((x.aliases?.[0]||x.expression||'').slice(0,130))}</summary><div class="sr-note">${esc((x.roles||[]).join(', '))}</div>${code({formula:x.expression,grain:x.grain,scope_population:x.row_context,upstream_scopes:x.upstream_scopes,execution_contract:x.execution_contract,source_history_ids:(x.evidence_ids||[]).map(id=>o.sources.find(s=>s.evidence_id===id)?.history_id||id)})}</details>`).join('')}</div></details>`;
 $('#schemawrap').insertAdjacentHTML('afterbegin',schema);$('#kbwrap').innerHTML=business;if(!kb.length)$('#kbwrap .sr-kb-scroll').innerHTML='<p class="sr-note">No additional saved business definitions for this schema. Physical schema and query evidence are available.</p>';
};
columnRows=function(){const rows=originalColumnRows();if(!state.reveal)return rows;const known=new Set(state.db.ontology.objects.flatMap(o=>o.physical_identifiers||[]));return rows.filter(row=>known.has(row.physical));};
drawOntology=function(){cancelBuild();state.reveal=null;$('#ontology').innerHTML=`<div class="sr-heading"><h2>Ontology construction / 本体构建</h2><span class="badge">Archived source replay</span></div><p class="sr-note">Run replays saved source contributions, recovered column names, semantic objects, relationships and coupled family reconstruction.</p><div class="sr-replay-controls"><button id="build-replay" class="replay">▶ Run</button><button id="build-step" class="ghost">Next step →</button><button id="build-stop" class="ghost">Stop</button><span id="build-position" class="sr-note">Ready · ${state.db.ontology.sources.length} saved source contributions</span></div><div id="build-stream" class="sr-build-stream"><div class="empty">Click Run to follow construction from SQL history.</div></div><div id="build-result"></div>`;
 const full=state.db;let cursor=0;const events=[];const batch=Math.max(1,Math.ceil(full.ontology.sources.length/18));for(let i=0;i<full.ontology.sources.length;i+=batch)events.push({kind:'sources',count:Math.min(i+batch,full.ontology.sources.length),label:'Read source contributions '+(i+1)+'–'+Math.min(i+batch,full.ontology.sources.length)});events.push({kind:'edges',label:'Bind saved relationships'});for(const c of full.ontology.construct)events.push({kind:'construct',record:c,label:'Construct coupled family · '+c.table});events.push({kind:'done',label:'Ontology ready for query retrieval'});
 function reset(){cancelBuild();cursor=0;state.reveal={sources:0,edges:false,construct:[]};$('#build-stream').innerHTML='';$('#build-result').innerHTML='';}
 function step(){if(!state.reveal)reset();if(cursor>=events.length)return false;const event=events[cursor++];if(event.kind==='sources')state.reveal.sources=event.count;if(event.kind==='edges')state.reveal.edges=true;if(event.kind==='construct')state.reveal.construct.push(event.record);const sources=full.ontology.sources.slice(0,state.reveal.sources),ids=new Set(sources.map(s=>s.evidence_id));const objects=full.ontology.objects.filter(o=>(o.evidence_ids||[]).some(id=>ids.has(id))).map(o=>{const contributions=sources.flatMap(s=>s.facts.filter(f=>f.id===o.id));return {...o,evidence_ids:o.evidence_ids.filter(id=>ids.has(id)),aliases:[...new Set(contributions.flatMap(f=>f.aliases||[]))]};});const active={...full,ontology:{...full.ontology,sources,objects,recovery:full.ontology.recovery,edges:state.reveal.edges?full.ontology.edges:[],construct:state.reveal.construct}};
 const stream=$('#build-stream');stream.insertAdjacentHTML('beforeend',`<details class="sr-task-event" open><summary>${cursor}. ${esc(event.label)}</summary><span class="sr-note">${sources.length} source records · ${objects.length} semantic objects · ${active.ontology.edges.length} edges</span>${event.kind==='sources'?code(sources.slice(-batch).map(s=>({history_id:s.history_id,sql:s.sql,extracted_objects:s.facts.length}))):event.kind==='construct'?code({status:event.record.status,selected_assignment:event.record.selected_assignment}):''}</details>`);stream.scrollTop=stream.scrollHeight;$('#build-position').textContent=`Step ${cursor} / ${events.length}`;
 const holder=$('#build-result'),main=$('#ontology');const saved=state.db;state.db=active;const temp=document.createElement('section');temp.id='ontology';main.id='ontology-shell';holder.replaceChildren(temp);originalDrawOntology();temp.id='ontology-prefix';main.id='ontology';state.db=saved;temp.querySelector('.sr-heading')?.remove();temp.querySelector('.sr-flow')?.remove();temp.querySelectorAll('.badge').forEach(b=>b.textContent='Saved evidence');temp.querySelectorAll('h3').forEach(h=>{if(h.textContent.startsWith('Historical SQL sources'))h.textContent='Saved source records / '+sources.length;});
 // Deferred event handlers read the visible prefix while the original archive stays immutable.
 temp.querySelectorAll('[data-column]').forEach(b=>b.onclick=()=>{const prior=state.db;state.db=active;showColumn(b.dataset.column);state.db=prior;});const filter=temp.querySelector('#column-filter');filter.oninput=()=>{const prior=state.db;state.db=active;drawColumns();state.db=prior;};if(event.kind==='sources'&&typeof highlightCurrentHistorySQL==='function')highlightCurrentHistorySQL(sources.slice(-batch));if(state.historySQL?.selected){const selected=state.historySQL.records?.find(row=>row.key===state.historySQL.selected);if(selected)showHistorySupport(selected);}const sf=temp.querySelector('#source-filter');sf.oninput=()=>{const prior=state.db;state.db=active;drawSources();state.db=prior;};return cursor<events.length;}
 function play(){const speed=Number($('#replaySpeed').value);if(speed===0){while(step()){}return;}if(step())state.buildTimer=setTimeout(play,650/speed);}
 $('#build-replay').onclick=()=>{reset();play();};$('#build-step').onclick=()=>{cancelBuild();step();};$('#build-stop').onclick=cancelBuild;
};
drawMaintenance=function(){originalDrawMaintenance();const body=$('#maintenance-body'),full=body.innerHTML;body.innerHTML='<div class="empty">Click Run to apply the selected source event and inspect its affected closure.</div>';const controls=document.createElement('div');controls.className='sr-replay-controls';controls.innerHTML='<button id="maint-run" class="replay">▶ Run update</button><button id="maint-next" class="ghost">Next step →</button><button id="maint-stop" class="ghost">Stop</button><span id="maint-position" class="sr-note">Ready</span>';$('#maintenance-event').after(controls);let cursor=0;function reset(){cancelBuild();cursor=0;body.innerHTML='';}function step(){const event=state.db.maintenance?.[Number($('#maintenance-event').value)];if(!event){body.innerHTML='<div class="empty">No source update event selected.</div>';return false;}const r=event.receipt;const labels=['Read source / interpretation correction','Seed changed semantic objects','Expand forward dependency closure','Apply changed aliases and preserve unaffected columns'];if(cursor<3){body.insertAdjacentHTML('beforeend',`<div class="sr-card"><h3>${cursor+1}. ${labels[cursor]}</h3>${code(cursor===0?{source:event.source,event_type:event.event_type,column_changes:event.column_changes}:cursor===1?{delta_ids:r.delta_ids}:{affected_ids:r.affected_ids,preserved_object_count:r.unchanged_object_count})}</div>`);cursor++;}else{showMaintenance(Number($('#maintenance-event').value));cursor++;}$('#maint-position').textContent=`Step ${Math.min(cursor,4)} / 4`;return cursor<4;}function play(){const speed=Number($('#replaySpeed').value);if(speed===0){while(step()){}return;}if(step())state.maintenanceTimer=setTimeout(play,900/speed);}$('#maint-run').onclick=()=>{reset();play();};$('#maint-next').onclick=()=>{cancelBuild();step();};$('#maint-stop').onclick=cancelBuild;$('#maintenance-event').onchange=()=>{reset();body.innerHTML='<div class="empty">Click Run update to begin.</div>';};if(!state.db.maintenance?.length){$('#maint-run').disabled=true;$('#maint-next').disabled=true;body.innerHTML='<div class="empty">No saved update event for this schema. Import a SQL delta through Local API to inspect incremental maintenance.</div>';}};
function $$(s){return document.querySelectorAll(s);}
// Remove internal archive identifiers from the presentation controls.
$('#archiveSelect').options[0].textContent='Saved results';
function installDatasetSelector(){if(!state.catalog?.datasets)return;if(typeof installResultFilter==='function')installResultFilter();$('#archiveSelect').options[0].textContent='Saved results'+(state.catalog.total_questions?' · '+state.catalog.total_questions.toLocaleString()+' questions':'');let selector=$('#datasetSelect');if(!selector){selector=document.createElement('select');selector.id='datasetSelect';selector.setAttribute('aria-label','Benchmark');$('#left .sr-title').before(selector);}selector.innerHTML=state.catalog.datasets.map(d=>`<option value="${esc(d.id)}">${esc(d.label)}${d.question_count?' · '+d.question_count.toLocaleString():''}</option>`).join('');selector.value=state.dataset||'BIRD-History';selector.onchange=async()=>{stop();state.dataset=selector.value;const group=state.catalog.datasets.find(g=>g.id===state.dataset);state.catalog.databases=group.databases;$('.sr-title').textContent='DATABASES / '+group.databases.length;$('#db-search').value='';drawDatabases();const chosen=group.databases.find(db=>typeof resultCases==='function'?resultCases(db).length:db.cases.length)||group.databases[0];if(chosen)await selectDatabase(chosen.id);};}
json('data/catalog.json').then(()=>{installDatasetSelector();if(state.db){drawMiddle();drawOntology();drawMaintenance();}});
state.language=localStorage.getItem('sr-language')||'en';
function displayDatabase(id){const parts=id.split('::');return parts[0]==='evoschema'?parts[2]+' · '+parts[1].replace(/_/g,' '):id;}
const middleBeforeExplanations=drawMiddle;
drawMiddle=function(){middleBeforeExplanations();$('#detail h2').textContent=displayDatabase(state.db.database);const lang=state.language;const controls=document.createElement('div');controls.className='sr-explain-controls';controls.innerHTML=`<button id="schema-explain" class="ghost">${lang==='zh'?'查看本库Schema解析':'Schema explanation'}</button><button id="business-explain" class="ghost">${lang==='zh'?'查看业务口径解析':'Business semantics'}</button>`;$('#schemawrap').prepend(controls);$('#schema-explain').onclick=()=>loadExplanation(true);$('#business-explain').onclick=()=>loadExplanation(true);loadExplanation(false);};
async function loadExplanation(open){if(!state.db?.explanations)return;if(state.pendingDb)return;const key=state.dataset+'::'+state.db.database;const ticket=state.explanationEpoch=(state.explanationEpoch||0)+1;try{const guide=await json(state.db.explanations);if(ticket!==state.explanationEpoch||state.pendingDb||key!==state.dataset+'::'+state.db.database)return;const document=guide.documents[state.language];$('#explain').innerHTML=`<div class="sr-heading"><h2>${state.language==='zh'?'本库Schema与业务口径解析':'Database schema & business semantics'}</h2><a class="sr-doc-download" href="${esc(document.markdown)}" download>${state.language==='zh'?'下载解释文档':'Download guide'} ↗</a></div><p class="sr-note">${state.language==='zh'?'离线缓存 · 根据本库已保存schema、恢复别名、SQL来源及语义对象生成。':'Offline cached guide · generated from this database’s saved schema, recovered aliases, SQL sources and semantic objects.'}</p><article class="sr-guide">${document.html}</article>`;if(open)tab('explain');}catch(e){toast(e.message);}}
(function(){const button=document.createElement('button');button.className='ghost';button.id='langToggle';button.textContent=state.language==='en'?'中文':'English';button.onclick=()=>{state.language=state.language==='en'?'zh':'en';localStorage.setItem('sr-language',state.language);button.textContent=state.language==='en'?'中文':'English';if(state.db){drawMiddle();loadExplanation(state.tab==='explain');}};$('#api-open').before(button);const t=document.createElement('button');t.dataset.tab='explain';t.textContent='Schema explanation';t.onclick=()=>loadExplanation(true);$('#sr-tabs').appendChild(t);const s=document.createElement('section');s.id='explain';s.className='sr-view';$('#sr-content').appendChild(s);})();
// Keep the complete navigation hierarchy together in PASCAL's left column.
drawDatabases=function(){const search=$('#db-search').value.toLowerCase();$('#list').innerHTML=state.catalog.databases.filter(db=>[db.id,...db.cases.map(c=>c.question)].join(' ').toLowerCase().includes(search)).map(db=>`<details class="sr-db-tree" ${state.db?.database===db.id?'open':''}><summary class="dbhdr ${state.db?.database===db.id?'open sel':''}" data-db="${esc(db.id)}"><span class="caret">▶</span><span class="dbn">${esc(displayDatabase(db.id))}</span><span class="cnt">${db.cases.length} Q</span></summary><div class="sr-db-count">${db.columns} columns · ${db.sources} source records</div>${db.cases.length?db.cases.map(c=>`<button class="item task ${state.case?.id===c.id?'sel':''}" data-case="${esc(c.id)}" data-case-db="${esc(db.id)}"><span class="id">${esc(c.id)}</span><span class="sr-tree-question">${esc(c.question)}</span>${c.trace_available===false?`<span class="sr-tag">${esc(c.saved_status||'Saved status')}</span>`:''}</button>`).join(''):'<div class="empty sr-empty-small">No saved question in this selection.</div>'}</details>`).join('');document.querySelectorAll('[data-db]').forEach(row=>row.onclick=async event=>{event.preventDefault();if(state.db?.database===row.dataset.db){row.closest('details').open=!row.closest('details').open;return;}await selectDatabase(row.dataset.db);});document.querySelectorAll('[data-case]').forEach(row=>row.onclick=async()=>{const db=row.dataset.caseDb,id=row.dataset.case;if(state.db?.database!==db)await selectDatabase(db);if(state.db?.database===db)await selectCase(id);});};

// Query playback appends only reached frames, using the saved records in order.
function savedQueryFrames(){const c=state.case,p=c.prediction,trace=c.saved_native_trace||p,r=trace.react||{};const frames=[{kind:'question',title:'Question / 输入问题',data:{question:c.question,database:c.database,saved_status:p.status||p.decision,error:p.error}}];if(r.initial_search)frames.push({kind:'retrieval',title:'Ontology retrieval / 语义检索',data:r.initial_search});if(r.graph_evo_program_context||r.scope_contract_validation||r.semantic_memory)frames.push({kind:'context',title:'Bound evidence context / 证据上下文',data:{graph_evo_program_context:r.graph_evo_program_context,scope_contract_validation:r.scope_contract_validation,semantic_memory:r.semantic_memory}});for(const [index,usage]of(trace.audit?.usage||[]).entries())frames.push({kind:'model',title:'Recorded model call '+(index+1),data:usage});if(r.compiled_semantic_plan)frames.push({kind:'plan',title:'Compiled semantic plan / 语义计划',data:r.compiled_semantic_plan});for(const action of r.trajectory||[])frames.push({kind:'tool',title:action.tool+' · '+(action.status||'saved'),data:action});frames.push({kind:'final',title:'Saved submitted output / 保存结果',data:{sql:p.sql??'',status:p.status||p.decision,error:p.error,execution_probe:p.execution_probe}});return frames;}
function queryFrameHTML(frame,index){let body='';const data=frame.data||{};if(frame.kind==='question')body=`<p>${esc(data.question)}</p><p class="sr-note">${esc(state.dataset||'BIRD-History')} · ${esc(displayDatabase(data.database))} · ${esc(data.saved_status||'archived')}</p>`;else if(frame.kind==='retrieval'){const hits=data.results||[];body=`<p class="sr-note">${hits.length} saved evidence candidates</p>${hits.map(hit=>details('#'+hit.rank+' · '+(hit.kind||'')+' · '+(hit.physical_name||hit.evidence_candidate_id),hit)).join('')}${details('Role graph and physical anchors',Object.fromEntries(Object.entries(data).filter(([key])=>key!=='results')))}`;}else if(frame.kind==='tool'){const observation=data.observation||{};body=data.arguments?.sql?code(data.arguments.sql):code(data.arguments||{});if(observation.columns?.length)body+=`<table class="sr-table"><thead><tr>${observation.columns.map(c=>`<th>${esc(c)}</th>`).join('')}</tr></thead><tbody>${(observation.rows||[]).map(row=>`<tr>${row.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table>`;body+=details('Recorded observation',observation);}else if(frame.kind==='final'){body=(data.sql?code(data.sql):'<p class="sr-note">Saved SQL is empty.</p>')+details('Saved status and execution record',{status:data.status,error:data.error,execution_probe:data.execution_probe});}else body=details(frame.kind==='model'?'Saved model usage':'Saved evidence payload',data,frame.kind==='model');return `<article class="sr-card sr-query-frame" data-frame-index="${index}" data-frame-kind="${frame.kind}"><h3>${index+1}. ${esc(frame.title)}</h3>${body}</article>`;}
drawQuery=function(){stop();if(!state.case){$('#query').innerHTML=`<div class="sr-heading"><h2>Text-to-SQL / ${esc(displayDatabase(state.db.database))}</h2><span class="badge">${state.db.cases.length} saved queries</span></div><div class="empty">Select a question in the left database tree.</div>`;return;}const c=state.case,frames=savedQueryFrames();state.queryCursor=0;$('#query').innerHTML=`<div class="sr-heading"><h2>${esc(c.id)}</h2><span class="badge">${c.origin==='archive'?'Saved archive':'Local API run'}</span></div><p class="sr-query-question">${esc(c.question)}</p><div class="sr-replay-controls"><button id="replay" class="replay">▶ Run</button><button id="next" class="ghost">Next event →</button><button id="stop" class="ghost">Stop</button><span id="sr-progress" class="sr-note">Ready · ${frames.length} saved events</span></div><div id="query-stream" aria-live="polite"><div class="empty">Click Run to replay this saved question.</div></div>`;function clear(){stop();state.queryCursor=0;$('#query-stream').innerHTML='';$('#sr-progress').textContent=`0 / ${frames.length} events`;}function append(){if(state.queryCursor>=frames.length)return false;if(state.queryCursor===0)$('#query-stream').innerHTML='';const index=state.queryCursor++;$('#query-stream').insertAdjacentHTML('beforeend',queryFrameHTML(frames[index],index));$('#sr-progress').textContent=`${state.queryCursor} / ${frames.length} events`;$('#query-stream').lastElementChild?.scrollIntoView({block:'nearest'});return state.queryCursor<frames.length;}playNext=function(){const speed=Number($('#replaySpeed').value);if(speed===0){while(append()){}return;}if(append())state.timer=setTimeout(playNext,1000/speed);};$('#replay').onclick=()=>{clear();playNext();};$('#next').onclick=()=>{stop();append();};$('#stop').onclick=stop;};
